import{_ as e,o as t,c as r,ag as i}from"./chunks/framework.DTisvaUJ.js";const c=JSON.parse('{"title":"常见问题 — 安装、语音识别与朗读","description":"Mutelink常见问题：安装更新、识别、朗读、翻译、VR操作，以及免费和付费功能。","frontmatter":{"title":"常见问题 — 安装、语音识别与朗读","description":"Mutelink常见问题：安装更新、识别、朗读、翻译、VR操作，以及免费和付费功能。","head":[["meta",{"name":"robots","content":"index, follow, max-image-preview:large"}],["link",{"rel":"canonical","href":"https://utyujinn.github.io/Mutelink-releases/zh/help/faq"}],["meta",{"property":"og:type","content":"website"}],["meta",{"property":"og:site_name","content":"Mutelink"}],["meta",{"property":"og:locale","content":"zh_CN"}],["meta",{"property":"og:title","content":"常见问题 — 安装、语音识别与朗读 | Mutelink"}],["meta",{"property":"og:description","content":"Mutelink常见问题：安装更新、识别、朗读、翻译、VR操作，以及免费和付费功能。"}],["meta",{"property":"og:url","content":"https://utyujinn.github.io/Mutelink-releases/zh/help/faq"}],["meta",{"property":"og:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"property":"og:image:width","content":"1920"}],["meta",{"property":"og:image:height","content":"1080"}],["meta",{"property":"og:image:alt","content":"Mutelink"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"常见问题 — 安装、语音识别与朗读 | Mutelink"}],["meta",{"name":"twitter:description","content":"Mutelink常见问题：安装更新、识别、朗读、翻译、VR操作，以及免费和付费功能。"}],["meta",{"name":"twitter:image","content":"https://utyujinn.github.io/Mutelink-releases/images/og-image.png"}],["meta",{"name":"twitter:image:alt","content":"Mutelink"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://utyujinn.github.io/Mutelink-releases/help/faq"}],["link",{"rel":"alternate","hreflang":"en","href":"https://utyujinn.github.io/Mutelink-releases/en/help/faq"}],["link",{"rel":"alternate","hreflang":"zh-Hans","href":"https://utyujinn.github.io/Mutelink-releases/zh/help/faq"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://utyujinn.github.io/Mutelink-releases/ko/help/faq"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://utyujinn.github.io/Mutelink-releases/help/faq"}]]},"headers":[],"relativePath":"zh/help/faq.md","filePath":"zh/help/faq.md"}'),n={name:"zh/help/faq.md"};function o(l,a,h,s,u,p){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="q-a" tabindex="-1">Q&amp;A <a class="header-anchor" href="#q-a" aria-label="Permalink to &quot;Q&amp;A {#q-a}&quot;">​</a></h1><p>以下为常见问题。遇到故障请查看<a href="/Mutelink-releases/zh/help/troubleshooting">故障排除</a>。</p><h2 id="インストール・更新" tabindex="-1">安装与更新 <a class="header-anchor" href="#インストール・更新" aria-label="Permalink to &quot;安装与更新 {#インストール・更新}&quot;">​</a></h2><h3 id="「windowsによってpcが保護されました」と出ます" tabindex="-1">提示“Windows已保护你的电脑” <a class="header-anchor" href="#「windowsによってpcが保護されました」と出ます" aria-label="Permalink to &quot;提示“Windows已保护你的电脑” {#「windowsによってpcが保護されました」と出ます}&quot;">​</a></h3><p>应用未代码签名，可能出现该提示。点击“更多信息”后选择“仍要运行”，无需管理员权限。</p><h3 id="新しいバージョンが出たことは、どうやって分かりますか" tabindex="-1">如何得知新版本？ <a class="header-anchor" href="#新しいバージョンが出たことは、どうやって分かりますか" aria-label="Permalink to &quot;如何得知新版本？ {#新しいバージョンが出たことは、どうやって分かりますか}&quot;">​</a></h3><p>应用启动时会通知，也可在设置 &gt; 其他 &gt; 关于中检查。</p><h3 id="設定の説明は、どこにありますか" tabindex="-1">哪里有设置说明？ <a class="header-anchor" href="#設定の説明は、どこにありますか" aria-label="Permalink to &quot;哪里有设置说明？ {#設定の説明は、どこにありますか}&quot;">​</a></h3><p>点击设置右上角的“？”即可显示各项说明。本站不逐项列出所有设置。</p><h3 id="設定の項目が、少なく見えます" tabindex="-1">为什么设置项看起来较少？ <a class="header-anchor" href="#設定の項目が、少なく見えます" aria-label="Permalink to &quot;为什么设置项看起来较少？ {#設定の項目が、少なく見えます}&quot;">​</a></h3><p>设置 &gt; 使用方式会根据用途仅显示所需选项。想查看全部时，在同页选择“显示全部”。</p><h2 id="音声認識" tabindex="-1">语音识别 <a class="header-anchor" href="#音声認識" aria-label="Permalink to &quot;语音识别 {#音声認識}&quot;">​</a></h2><h3 id="音声認識のエンジンは、どれを選べばいいですか" tabindex="-1">应该选择哪种识别引擎？ <a class="header-anchor" href="#音声認識のエンジンは、どれを選べばいいですか" aria-label="Permalink to &quot;应该选择哪种识别引擎？ {#音声認識のエンジンは、どれを選べばいいですか}&quot;">​</a></h3><p>日语建议Parakeet日语TDT或Haas-ja，英语建议Parakeet英语，其他语言建议Qwen3-ASR或Whisper turbo。详见<a href="/Mutelink-releases/zh/compare/speech-recognition">引擎对比</a>。</p><h3 id="声を、pcの外に出したくありません" tabindex="-1">不想把音频发到电脑外 <a class="header-anchor" href="#声を、pcの外に出したくありません" aria-label="Permalink to &quot;不想把音频发到电脑外 {#声を、pcの外に出したくありません}&quot;">​</a></h3><p>选择本地Parakeet、Haas-ja、Qwen3-ASR或Whisper turbo，音频不会外传。Web Speech/Google云端会发送至Microsoft或Google（<a href="/Mutelink-releases/zh/about/privacy">隐私</a>）。</p><h3 id="友達の名前が、正しく認識されません" tabindex="-1">朋友的名字识别不准确 <a class="header-anchor" href="#友達の名前が、正しく認識されません" aria-label="Permalink to &quot;朋友的名字识别不准确 {#友達の名前が、正しく認識されません}&quot;">​</a></h3><p>使用Parakeet日语TDT时，可在设置 &gt; 说话 &gt; 语言与识别 &gt; 单词和名字中注册，以提高出现概率。</p><h3 id="言語の「自動」が選べません" tabindex="-1">无法选择自动语言 <a class="header-anchor" href="#言語の「自動」が選べません" aria-label="Permalink to &quot;无法选择自动语言 {#言語の「自動」が選べません}&quot;">​</a></h3><p>仅Qwen3-ASR和Whisper turbo支持自动语言。</p><h2 id="読み上げの声" tabindex="-1">朗读声音 <a class="header-anchor" href="#読み上げの声" aria-label="Permalink to &quot;朗读声音 {#読み上げの声}&quot;">​</a></h2><h3 id="どの声を選べばいいですか" tabindex="-1">应该选择哪种声音？ <a class="header-anchor" href="#どの声を選べばいいですか" aria-label="Permalink to &quot;应该选择哪种声音？ {#どの声を選べばいいですか}&quot;">​</a></h3><p>不想用GPU或喜欢角色声音可选VOICEVOX；快速自然日语可选Irodori-TTS；其他语言可选Qwen3-TTS。可在<a href="/Mutelink-releases/zh/compare/voices">声音对比</a>试听。</p><h3 id="gpuは必要ですか" tabindex="-1">需要GPU吗？ <a class="header-anchor" href="#gpuは必要ですか" aria-label="Permalink to &quot;需要GPU吗？ {#gpuは必要ですか}&quot;">​</a></h3><p>仅用VOICEVOX或聊天框无需GPU。Irodori-TTS和Qwen3-TTS需支持Vulkan的GPU。</p><h3 id="自分の声に似せた声で、読み上げられますか" tabindex="-1">可以使用与自己相似的声音吗？ <a class="header-anchor" href="#自分の声に似せた声で、読み上げられますか" aria-label="Permalink to &quot;可以使用与自己相似的声音吗？ {#自分の声に似せた声で、読み上げられますか}&quot;">​</a></h3><p>可在Irodori-TTS或Qwen3-TTS中注册录音（<a href="/Mutelink-releases/zh/about/supporter">支持版功能</a>）。仅可使用本人的声音或取得所有者明确同意的声音。</p><h3 id="日本語以外も、読み上げられますか" tabindex="-1">能朗读日语以外的语言吗？ <a class="header-anchor" href="#日本語以外も、読み上げられますか" aria-label="Permalink to &quot;能朗读日语以外的语言吗？ {#日本語以外も、読み上げられますか}&quot;">​</a></h3><p>Qwen3-TTS可朗读英语、中文、韩语、德语、西班牙语、法语、意大利语、葡萄牙语和俄语。</p><h2 id="翻訳" tabindex="-1">翻译 <a class="header-anchor" href="#翻訳" aria-label="Permalink to &quot;翻译 {#翻訳}&quot;">​</a></h2><h3 id="翻訳は無料ですか" tabindex="-1">翻译免费吗？ <a class="header-anchor" href="#翻訳は無料ですか" aria-label="Permalink to &quot;翻译免费吗？ {#翻訳は無料ですか}&quot;">​</a></h3><p>翻译本身、译文发送到聊天框及对方语音翻译免费。仅译文朗读需要<a href="/Mutelink-releases/zh/about/supporter">支持版</a>。</p><h3 id="どの翻訳エンジンがいいですか" tabindex="-1">哪个翻译引擎更好？ <a class="header-anchor" href="#どの翻訳エンジンがいいですか" aria-label="Permalink to &quot;哪个翻译引擎更好？ {#どの翻訳エンジンがいいですか}&quot;">​</a></h3><p>取决于语言。请查看<a href="/Mutelink-releases/zh/compare/translation">翻译对比</a>中的实际译文后选择。不想外传文本时可选PLaMo或TranslateGemma。</p><h3 id="訳した文を、確認してから送れますか" tabindex="-1">能确认译文后再发送吗？ <a class="header-anchor" href="#訳した文を、確認してから送れますか" aria-label="Permalink to &quot;能确认译文后再发送吗？ {#訳した文を、確認してから送れますか}&quot;">​</a></h3><p>不能。发送前即时翻译并直接发送。</p><h2 id="聞こえた声" tabindex="-1">对方语音 <a class="header-anchor" href="#聞こえた声" aria-label="Permalink to &quot;对方语音 {#聞こえた声}&quot;">​</a></h2><h3 id="聞こえた声とは何ですか" tabindex="-1">什么是对方语音功能？ <a class="header-anchor" href="#聞こえた声とは何ですか" aria-label="Permalink to &quot;什么是对方语音功能？ {#聞こえた声とは何ですか}&quot;">​</a></h3><p>Mutelink识别VRChat中的声音并以文字显示对方的话，也可显示译文。</p><h3 id="聞こえた声は、相手に見えますか" tabindex="-1">对方能看到识别文字吗？ <a class="header-anchor" href="#聞こえた声は、相手に見えますか" aria-label="Permalink to &quot;对方能看到识别文字吗？ {#聞こえた声は、相手に見えますか}&quot;">​</a></h3><p>主界面列表和VR面板仅自己可见。若开启聊天框输出（默认关闭），实例中所有人都可见。</p><h2 id="vr" tabindex="-1">VR <a class="header-anchor" href="#vr" aria-label="Permalink to &quot;VR {#vr}&quot;">​</a></h2><h3 id="steamvrは必須ですか" tabindex="-1">必须使用SteamVR吗？ <a class="header-anchor" href="#steamvrは必須ですか" aria-label="Permalink to &quot;必须使用SteamVR吗？ {#steamvrは必須ですか}&quot;">​</a></h3><p>不是。不用SteamVR也可在桌面使用，并支持发送、切换语言等快捷键（设置 &gt; 其他 &gt; 快捷键）。</p><h3 id="steamvrと一緒に、起動できますか" tabindex="-1">可以随SteamVR启动吗？ <a class="header-anchor" href="#steamvrと一緒に、起動できますか" aria-label="Permalink to &quot;可以随SteamVR启动吗？ {#steamvrと一緒に、起動できますか}&quot;">​</a></h3><p>可以。在设置 &gt; 外观 &gt; VR中开启“随SteamVR启动和退出”。连接时才会注册，因此首次请先启动SteamVR再启动Mutelink。</p><h2 id="支援版・データ" tabindex="-1">支持版与数据 <a class="header-anchor" href="#支援版・データ" aria-label="Permalink to &quot;支持版与数据 {#支援版・データ}&quot;">​</a></h2><h3 id="支援版を買わないと、使えませんか" tabindex="-1">不买支持版就不能用吗？ <a class="header-anchor" href="#支援版を買わないと、使えませんか" aria-label="Permalink to &quot;不买支持版就不能用吗？ {#支援版を買わないと、使えませんか}&quot;">​</a></h3><p>不需要，应用本体免费。区别见<a href="/Mutelink-releases/zh/about/supporter">支持版说明</a>。</p><h3 id="どんなデータが、外に送られますか" tabindex="-1">哪些数据会发往外部？ <a class="header-anchor" href="#どんなデータが、外に送られますか" aria-label="Permalink to &quot;哪些数据会发往外部？ {#どんなデータが、外に送られますか}&quot;">​</a></h3><p>详见<a href="/Mutelink-releases/zh/about/privacy">隐私</a>。</p>',51)])])}const m=e(n,[["render",o]]);export{c as __pageData,m as default};
